import {questionImage} from './visuals.js';
import {resolveAnswer} from './core.js';

const $=s=>document.querySelector(s),main=$('#content');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
let roomId=params.get('room')||'',pin=params.get('pin')||'',guestToken='',session=null,state=null,qr='',timer=null,poll=null,clockOffset=0,lastView='',recognition=null;
try{guestToken=sessionStorage.getItem('geovoice-live-token:'+roomId)||'';}catch{}
function notice(message){const el=$('#message');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),6500);}
async function request(path,method='GET',body,asGuest=false){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);let response;
 try{response=await fetch('/api/live'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-GeoVoice':'1',...(session?.csrf?{'X-CSRF-Token':session.csrf}:{}),...(asGuest&&guestToken?{'X-Live-Token':guestToken}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:controller.signal});}catch{throw new Error('Could not reach GeoVoice. Check your connection and try again.');}finally{clearTimeout(timeout);}
 const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Request failed.');return data;
}
function saveToken(id,raw){roomId=id;guestToken=raw;try{sessionStorage.setItem('geovoice-live-token:'+id,raw);}catch{}history.replaceState(null,'','./live.html?room='+encodeURIComponent(id));}
function navRoom(id){roomId=id;history.replaceState(null,'','./live.html?room='+encodeURIComponent(id));void refresh();}
function setup(){lastView='setup';main.innerHTML=`<section class="setup"><span class="eyebrow">THE WORLD IS YOUR GAME BOARD</span><h1>Play together, explore together.</h1><div class="setup-grid"><section class="card"><h2>Host a live expedition</h2><p>Share a PIN or QR code. Up to 30 explorers can join.</p><form id="host-form"><label for="category">Topic</label><select id="category"><option value="All">All geography topics</option>${(session?.config?.categories||[]).map(c=>`<option>${esc(c)}</option>`).join('')}</select><label for="count">Questions</label><select id="count"><option value="5">5 questions</option><option value="10" selected>10 questions</option></select><label for="seconds">Time per question</label><select id="seconds"><option value="20">20 seconds</option><option value="30" selected>30 seconds</option><option value="45">45 seconds</option></select><label class="radio"><input id="teams" type="checkbox"> Team mode · host assigns teams</label><button class="button primary full" ${session?.stage==='full'?'':'disabled'}>Create live game →</button></form>${session?.stage==='full'?'':'<p>To host, <a href="./">sign in to GeoVoice</a>. Guests can join below.</p>'}</section><section class="card poster"><span class="eyebrow">JOIN THE JOURNEY</span><h2>Have a game PIN?</h2><p>Enter the PIN and a nickname to join from this device. No account is needed.</p><form id="pin-form"><label for="pin">Six-digit PIN</label><input id="pin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" value="${esc(pin)}" required><button class="button full">Find game →</button></form></section></div></section>`;
 $('#host-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const data=await request('/rooms','POST',{category:$('#category').value,count:Number($('#count').value),seconds:Number($('#seconds').value),teamMode:$('#teams').checked});qr=data.qr;navRoom(data.id);}catch(error){notice(error.message);button.disabled=false;}};
 $('#pin-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const data=await request('/pin/'+$('#pin').value.trim());pin=data.pin;roomId=data.id;join(data);}catch(error){notice(error.message);button.disabled=false;}};
}
function join(found){lastView='join';main.innerHTML=`<section class="card join-card"><span class="eyebrow">JOIN EXPEDITION · PIN ${esc(found.pin)}</span><h1>What should we call you?</h1><p>Pick a nickname for this game. The host will see it in the lobby.</p><form id="join-form" class="setup"><label for="nickname">Nickname</label><input id="nickname" minlength="2" maxlength="24" required autocomplete="nickname" placeholder="Your explorer name"><button class="button primary full">Join lobby →</button></form><p><button class="button light" id="back">Use another PIN</button></p></section>`;
 $('#back').onclick=setup;$('#join-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const data=await request('/rooms/'+roomId+'/join','POST',{name:$('#nickname').value.trim()});saveToken(roomId,data.token);await refresh();}catch(error){notice(error.message);button.disabled=false;}};
}
async function act(action,body){try{await request('/rooms/'+roomId+'/'+action,'POST',body,action==='answer');await refresh();}catch(error){notice(error.message);}}
function lobby(s){lastView='lobby';const isHost=s.isHost;main.innerHTML=`<span class="eyebrow">READY TO EXPLORE · ${esc(s.category)}</span><div class="lobby-head"><div><h1>Gather your explorers.</h1><p>${s.teamMode?'Team expedition':'Solo leaderboard'} · ${s.total} questions · ${s.questionMs/1000} seconds each</p></div><span class="chip">${s.players.length} / 30 players</span></div><div class="lobby-grid"><section class="card"><span class="eyebrow">GAME PIN</span><div class="pin">${esc(s.pin.slice(0,3))} ${esc(s.pin.slice(3))}</div><p>Guests can enter this PIN on GeoVoice or scan the QR code.</p><a class="link" href="${esc(s.joinUrl)}">${esc(s.joinUrl)}</a><div class="actions">${isHost?'<button class="button light" id="copy">Copy join link</button><button class="button primary" id="start" '+(!s.players.length||s.teamMode&&s.players.some(p=>!p.team)?'disabled':'')+'>Start game →</button>':''}</div>${isHost&&s.teamMode&&s.players.some(p=>!p.team)?'<p class="muted">Assign every player to a team before starting.</p>':''}</section><section class="card"><span class="eyebrow">SCAN TO JOIN</span><div>${s.qr?`<img class="qr" src="${s.qr}" alt="QR code to join this game">`:`<div class="qr" id="qr-placeholder">QR code is shown on the host's screen</div>`}</div><h2>Explorer lobby</h2><div class="people">${s.players.length?s.players.map(p=>`<div class="person"><strong>${esc(p.name)}</strong>${s.teamMode?(isHost?`<select class="team-select" data-player="${esc(p.id)}"><option value="">Assign team</option><option value="Atlas" ${p.team==='Atlas'?'selected':''}>Atlas</option><option value="Voyagers" ${p.team==='Voyagers'?'selected':''}>Voyagers</option></select>`:`<span class="team-tag">${esc(p.team||'Waiting for team')}</span>`):''}</div>`).join(''):'<p class="muted">Waiting for players to join…</p>'}</div></section></div>`;
 $('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(s.joinUrl);notice('Join link copied.');}catch{notice('Copy the link shown above.');}});
 $('#start')?.addEventListener('click',()=>act('start'));
 document.querySelectorAll('[data-player]').forEach(select=>select.onchange=()=>act('team',{playerId:select.dataset.player,team:select.value}));
}
function leaders(s){return `<section class="card"><span class="eyebrow">LIVE LEADERBOARD</span><h2>Explorer standings</h2>${s.players.length?s.players.map((p,i)=>`<div class="leader"><span class="rank">${i+1}</span><strong>${esc(p.name)}</strong>${p.team?`<span class="team-tag">${esc(p.team)}</span>`:''}<span class="points">${p.points} pts</span></div>`).join(''):'<p>No players yet.</p>'}</section>`;}
function stage(s){lastView='stage';const q=s.question,image=questionImage(q),selected=s.myAnswer,reveal=s.reveal,canAnswer=!s.isHost&&s.status==='question'&&selected===null;
 const feedback=s.status==='paused'?'Game paused by the host.':reveal?`Correct: ${esc(q.options[reveal.correctIndex])}. ${esc(reveal.explanation||'')}`:s.isHost?`${s.answeredCount} of ${s.players.length} players answered.`:selected!==null?'Answer locked. Waiting for the round to end.':'Choose an option, type an answer, or use your voice.';
 main.innerHTML=`<div class="stage-top"><div><span class="chip">PIN ${esc(s.pin)}</span><span class="chip">ROUND ${s.roundIndex+1} / ${s.total}</span><span class="chip">${s.players.length} explorers</span></div><div><span class="chip clock" id="clock">--</span>${s.isHost?(s.status==='paused'?'<button class="button light" id="resume">Resume</button>':s.status==='question'||s.status==='feedback'?'<button class="button light" id="pause">Pause</button>':'')+'<button class="button danger" id="end">End game</button>':''}</div></div><div class="stage"><section class="card question-card"><span class="eyebrow">${esc(q.category)} · ${esc(q.difficulty||'Explore')}</span><h1>${esc(q.prompt)}</h1><div class="options">${q.options.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${reveal?(i===reveal.correctIndex?'correct':selected===i?'wrong':''):''}" data-answer="${i}" ${canAnswer?'':'disabled'}><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div><div class="feedback" role="status">${feedback}</div>${canAnswer?`<form id="type-answer" class="voice-tools"><input id="typed" maxlength="120" placeholder="Type option or answer" aria-label="Type answer"><button class="button light">Submit</button><button type="button" class="button light" id="mic">🎙 Speak</button></form><div id="voice-status" class="voice-status" role="status"></div>`:''}</section><figure class="scene ${image.fit==='contain'?'contain':''}"><img src="./images/${esc(image.file)}" alt="${esc(image.alt)}"><figcaption>${esc(image.label)} · Geography context</figcaption>${s.status==='paused'?'<div class="paused">Expedition paused</div>':''}</figure></div><div class="stage-bottom">${leaders(s)}<section class="card"><span class="eyebrow">${s.teamMode?'TEAM SCORES':'YOUR EXPEDITION'}</span><h2>${s.teamMode?'Together, further.':'Keep exploring.'}</h2>${s.teamMode?s.teams.map(t=>`<div class="leader"><strong>${esc(t.name)}</strong><span class="points">${t.points} pts</span></div>`).join(''):`<p>${s.isHost?'Watch the live standings as explorers answer.':'Correct answers earn 600 points plus up to 400 speed points.'}</p>`}<p class="muted">The next round starts automatically after a six-second answer reveal.</p></section></div>`;
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));
 $('#pause')?.addEventListener('click',()=>act('pause'));$('#resume')?.addEventListener('click',()=>act('resume'));$('#end')?.addEventListener('click',()=>{if(confirm('End this live game for everyone?'))act('end');});
 $('#type-answer')?.addEventListener('submit',e=>{e.preventDefault();const index=resolveAnswer($('#typed').value,q.options);if(index===null)notice('Enter an option letter or an exact answer.');else answer(index);});
 $('#mic')?.addEventListener('click',()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){notice('Voice recognition is unavailable here. Use an answer button or type.');return;}recognition?.abort();recognition=new Speech();recognition.lang='en-US';recognition.interimResults=false;$('#voice-status').textContent='Listening…';recognition.onresult=e=>{const heard=e.results[0][0].transcript,index=resolveAnswer(heard,q.options);$('#voice-status').textContent='Heard: '+heard;if(index===null)notice('I heard you, but could not match an option. Try again or tap it.');else answer(index);};recognition.onerror=()=>{$('#voice-status').textContent='Microphone unavailable. Tap or type an answer.';};recognition.start();});
 updateClock();
}
async function answer(index){recognition?.abort();document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);await act('answer',{selected:index});}
function finished(s){lastView='finished';main.innerHTML=`<section class="setup"><span class="eyebrow">EXPEDITION COMPLETE</span><h1>What a journey!</h1><div class="stage-bottom">${leaders(s)}<section class="card"><h2>${s.teamMode?'Team standings':'Thanks for playing'}</h2>${s.teamMode?s.teams.map(t=>`<div class="leader"><strong>${esc(t.name)}</strong><span class="points">${t.points} pts</span></div>`).join(''):'<p>Explore another part of the world together.</p>'}<a class="button primary" href="./live.html">New expedition →</a></section></div></section>`;}
function updateClock(){const el=$('#clock');if(!el||!state)return;if(state.status==='paused'){el.textContent='PAUSED';return;}if(state.status==='feedback')el.textContent='REVEAL';else el.textContent=Math.max(0,Math.ceil((Number(state.deadline)-Date.now()-clockOffset)/1000))+'s';}
async function refresh(){if(!roomId)return;try{const s=await request('/rooms/'+roomId,'GET',undefined,Boolean(guestToken));state=s;pin=s.pin;clockOffset=Date.now()-s.serverNow;$('#room-meta').textContent=`PIN ${s.pin} · ${s.status.toUpperCase()}`;const key=[s.status,s.roundIndex,s.players.map(p=>p.id+':'+p.points+':'+p.team).join('|'),s.answeredCount,s.myAnswer].join('/');if(key!==lastView){if(s.status==='lobby')lobby(s);else if(s.status==='finished')finished(s);else stage(s);lastView=key;}updateClock();}catch(error){notice(error.message);if(!state){roomId='';setup();}}}
async function init(){try{const [config,response]=await Promise.all([fetch('/api/config').then(r=>r.json()),fetch('/api/session').then(r=>r.json())]);session={...response,config};}catch{session={stage:'anonymous',config:{categories:[]}};}
 if(roomId){await refresh();}else if(/^\d{6}$/.test(pin)){try{const found=await request('/pin/'+pin);roomId=found.id;join(found);}catch(error){notice(error.message);setup();}}else setup();poll=setInterval(()=>{if(roomId)void refresh();},1800);timer=setInterval(updateClock,250);
}
void init();
